// ignore_for_file: prefer_final_locals

import 'dart:io';

import 'package:analyzer/dart/analysis/utilities.dart';
import 'package:analyzer/dart/ast/ast.dart';
import 'package:analyzer/dart/ast/visitor.dart';

const _marker =
    '// Generated by large_library_splitter.dart; keep changes in the source library.';
const _defaultMinimumLines = 500;
const _defaultMaximumPartLines = 420;

void main(List<String> args) {
  final root = Directory(
    _argument(args, '--root') ?? _repositoryRoot(),
  ).absolute;
  final minimumLines = int.tryParse(_argument(args, '--min-lines') ?? '') ??
      _defaultMinimumLines;
  final maximumPartLines =
      int.tryParse(_argument(args, '--max-part-lines') ?? '') ??
          _defaultMaximumPartLines;
  final scope = _argument(args, '--scope');
  final includeTests = args.contains('--include-tests');
  final resplit = args.contains('--resplit');
  final generatedOnly = args.contains('--generated-only');
  if (generatedOnly && !resplit) {
    throw ArgumentError('--generated-only requires --resplit');
  }
  final splitSuffix = generatedOnly ? '_resplit2' : (resplit ? '_resplit' : '');
  final apply = args.contains('--apply');
  final audit = args.contains('--audit');
  final repair = args.contains('--repair');
  if (repair) {
    _repairGeneratedVisibility(root, includeTests: includeTests);
    _repairGeneratedDirectives(
      root,
      includeTests: includeTests,
    );
    return;
  }
  if (audit) {
    _auditGeneratedCheckout(
      root,
      includeTests: includeTests,
    );
    stdout
        .writeln('Current checkout matches the generated large-library split.');
    return;
  }
  final plan = _SplitPlan.build(
    root,
    minimumLines: minimumLines,
    maximumPartLines: maximumPartLines,
    includeTests: includeTests,
    resplit: resplit,
    generatedOnly: generatedOnly,
    splitSuffix: splitSuffix,
    scope: scope,
  );

  _verifyPlan(plan);
  _printPlan(plan);
  if (!apply) {
    stdout.writeln('Dry run only. Pass --apply to write the verified split.');
    return;
  }

  _applyPlan(plan);
  stdout.writeln('Verified large-library split applied successfully.');
}

String? _argument(List<String> args, String name) {
  final index = args.indexOf(name);
  if (index == -1 || index + 1 >= args.length) return null;
  return args[index + 1];
}

String _repositoryRoot() {
  final script = File.fromUri(Platform.script).absolute;
  return script.parent.parent.parent.parent.path;
}

String _relativePath(String fromDirectory, String toPath) {
  final from = _normalPath(fromDirectory).split('/');
  final to = _normalPath(toPath).split('/');
  var common = 0;
  while (common < from.length &&
      common < to.length &&
      from[common] == to[common]) {
    common++;
  }
  final parts = <String>[];
  parts.addAll(List<String>.filled(from.length - common, '..'));
  parts.addAll(to.sublist(common));
  return parts.isEmpty ? '.' : parts.join('/');
}

String _normalPath(String path) => path.replaceAll('\\', '/');

String _canonicalPath(String path) {
  final normalized = _normalPath(path);
  final absolute = normalized.startsWith('/');
  final parts = <String>[];
  for (final part in normalized.split('/')) {
    if (part.isEmpty || part == '.') continue;
    if (part == '..') {
      if (parts.isNotEmpty && parts.last != '..') {
        parts.removeLast();
      } else if (!absolute) {
        parts.add(part);
      }
      continue;
    }
    parts.add(part);
  }
  final result = parts.join('/');
  return absolute ? '/$result' : result;
}

File _canonicalFile(String path) => File(_canonicalPath(path));

String _basename(String path) {
  final normalized = _normalPath(path);
  return normalized.substring(normalized.lastIndexOf('/') + 1);
}

String _withoutExtension(String path) {
  final name = _basename(path);
  final dot = name.lastIndexOf('.');
  return dot == -1 ? name : name.substring(0, dot);
}

int _lineCount(String source) {
  if (source.isEmpty) return 0;
  final newlines = '\n'.allMatches(source).length;
  return source.endsWith('\n') ? newlines : newlines + 1;
}

String _readGitStatus(Directory root) {
  final result = Process.runSync(
    'git',
    ['-C', root.path, 'status', '--porcelain=v1', '--untracked-files=all'],
  );
  if (result.exitCode != 0) {
    throw StateError('Unable to inspect git status: ${result.stderr}');
  }
  return result.stdout as String;
}

Set<String> _dirtyPaths(Directory root) {
  final status = _readGitStatus(root);
  final paths = <String>{};
  for (final line in status.split('\n')) {
    if (line.length < 4) continue;
    final path = line.substring(3).trim();
    if (path.isEmpty || path.contains(' -> ')) continue;
    paths.add(_normalPath(path));
  }
  return paths;
}

String _relativeToRoot(Directory root, File file) {
  return _relativePath(root.path, file.path);
}

String _partOfUri(File generatedFile, File libraryFile) {
  return _relativePath(generatedFile.parent.path, libraryFile.path);
}

String _partUri(File libraryFile, File generatedFile) {
  return _relativePath(libraryFile.parent.path, generatedFile.path);
}

String _safeIdentifier(String input) {
  final cleaned = input.replaceAll(RegExp(r'[^A-Za-z0-9_]'), '_');
  if (cleaned.isEmpty) return 'Part';
  if (RegExp(r'^[0-9]').hasMatch(cleaned)) return 'Part_$cleaned';
  return cleaned;
}

String _categoryFor(CompilationUnitMember declaration) {
  final name = switch (declaration) {
    ClassDeclaration item => item.namePart.typeName.lexeme,
    ClassTypeAlias item => item.name.lexeme,
    EnumDeclaration item => item.namePart.typeName.lexeme,
    ExtensionDeclaration item => item.name?.lexeme ?? 'extension',
    ExtensionTypeDeclaration item => item.primaryConstructor.typeName.lexeme,
    MixinDeclaration item => item.name.lexeme,
    FunctionDeclaration item => item.name.lexeme,
    TypeAlias item => item.name.lexeme,
    _ => 'declarations',
  };
  if (RegExp(
    r'(Model|Data|Result|Entry|Summary|Args|Options|Response|Request|State)$',
  ).hasMatch(name)) {
    return 'models';
  }
  if (RegExp(
    r'(Widget|Screen|Sheet|Card|Panel|Row|Column|Tile|View|Page|Dialog)',
  ).hasMatch(name)) {
    return 'widgets';
  }
  if (declaration is FunctionDeclaration ||
      RegExp(r'(parse|format|build|load|save|normalize|validate|resolve|map)',
              caseSensitive: false)
          .hasMatch(name)) {
    return 'helpers';
  }
  return 'declarations';
}

bool _isMovableTopLevel(CompilationUnitMember declaration) {
  return declaration is ClassDeclaration ||
      declaration is ClassTypeAlias ||
      declaration is EnumDeclaration ||
      declaration is ExtensionDeclaration ||
      declaration is ExtensionTypeDeclaration ||
      declaration is MixinDeclaration ||
      declaration is FunctionDeclaration ||
      declaration is TypeAlias;
}

int _annotatedStart(AstNode node) {
  if (node is AnnotatedNode && node.metadata.isNotEmpty) {
    return node.metadata.first.offset;
  }
  return node.offset;
}

bool _hasOverrideAnnotation(MethodDeclaration method) {
  return method.metadata.any(
    (annotation) => annotation.name.toSource() == 'override',
  );
}

bool _isMovableMethod(
  MethodDeclaration method, {
  bool allowAccessors = false,
}) {
  if (method.isStatic || method.externalKeyword != null) return false;
  if (!allowAccessors && (method.isGetter || method.isSetter)) return false;
  if (method.body is EmptyFunctionBody) return false;
  if (_hasOverrideAnnotation(method)) return false;
  const lifecycleNames = <String>{
    'activate',
    'build',
    'computeDryLayout',
    'createElement',
    'createRenderObject',
    'createState',
    'debugFillProperties',
    'deactivate',
    'didChangeDependencies',
    'didMountRenderObject',
    'didUpdateWidget',
    'dispose',
    'hitTest',
    'initState',
    'paint',
    'performLayout',
    'reassemble',
    'shouldRebuild',
    'shouldRepaint',
  };
  if (lifecycleNames.contains(method.name.lexeme)) return false;
  final source = method.toSource();
  if (RegExp(r'\bsuper\b').hasMatch(source)) return false;
  return true;
}

List<ClassMember> _classMembers(CompilationUnitMember declaration) {
  return switch (declaration) {
    ClassDeclaration item => item.body is BlockClassBody
        ? (item.body as BlockClassBody).members.toList()
        : const <ClassMember>[],
    ExtensionDeclaration item => item.body.members.toList(),
    _ => const <ClassMember>[],
  };
}

Set<String> _staticMemberNames(CompilationUnitMember declaration) {
  return _classMembers(declaration).expand<String>((member) {
    if (member is FieldDeclaration && member.isStatic) {
      return member.fields.variables.map((variable) => variable.name.lexeme);
    }
    if (member is MethodDeclaration && member.isStatic) {
      return <String>[member.name.lexeme];
    }
    return const <String>[];
  }).toSet();
}

String _qualifyStaticReferences(
  String methodSource,
  CompilationUnitMember declaration,
) {
  final staticNames = _staticMemberNames(declaration);
  if (staticNames.isEmpty) return methodSource;
  final extendedType = _classTargetSource(declaration);
  final qualifier = _staticQualifier(declaration);
  final wrapped =
      'extension _GeneratedStaticReferenceProbe on $extendedType {\n'
      '$methodSource\n}';
  final parsed = parseString(
    content: wrapped,
    throwIfDiagnostics: false,
  );
  if (parsed.errors.isNotEmpty) return methodSource;

  final edits = <_Range>[];
  parsed.unit.accept(
    _StaticReferenceVisitor(
      staticNames: staticNames,
      wrapperPrefixLength: wrapped.length - methodSource.length - 2,
      edits: edits,
    ),
  );
  if (edits.isEmpty) return methodSource;
  var output = methodSource;
  final sorted = edits.toList()..sort((a, b) => b.start.compareTo(a.start));
  for (final edit in sorted) {
    output = output.replaceRange(
      edit.start,
      edit.start,
      '$qualifier.',
    );
  }
  return output;
}

String _staticQualifier(CompilationUnitMember declaration) {
  return switch (declaration) {
    ClassDeclaration item => item.namePart.typeName.lexeme,
    ExtensionDeclaration item => item.onClause!.extendedType.toSource(),
    _ => throw StateError('Unsupported static-reference declaration.'),
  };
}

class _StaticReferenceVisitor extends RecursiveAstVisitor<void> {
  _StaticReferenceVisitor({
    required this.staticNames,
    required this.wrapperPrefixLength,
    required this.edits,
  });

  final Set<String> staticNames;
  final int wrapperPrefixLength;
  final List<_Range> edits;

  @override
  void visitSimpleIdentifier(SimpleIdentifier node) {
    final name = node.name;
    if (!staticNames.contains(name)) {
      super.visitSimpleIdentifier(node);
      return;
    }
    final previous = node.token.previous?.lexeme;
    if (previous == '.' || previous == '?.' || previous == r'$') {
      super.visitSimpleIdentifier(node);
      return;
    }
    final relativeOffset = node.offset - wrapperPrefixLength;
    if (relativeOffset >= 0) {
      edits.add(_Range(relativeOffset, relativeOffset));
    }
    super.visitSimpleIdentifier(node);
  }
}

String _classTargetSource(CompilationUnitMember declaration) {
  switch (declaration) {
    case ClassDeclaration item:
      final typeParameters = item.namePart.typeParameters;
      final parameters = typeParameters == null
          ? ''
          : typeParameters.typeParameters
              .map((parameter) => parameter.name.lexeme)
              .join(', ');
      return '${item.namePart.typeName.lexeme}${parameters.isEmpty ? '' : '<$parameters>'}';
    case ExtensionDeclaration item:
      final onClause = item.onClause;
      if (onClause == null) {
        throw StateError('Cannot split an extension without an on clause.');
      }
      return onClause.extendedType.toSource();
    default:
      throw StateError('Unsupported class-like declaration.');
  }
}

String _extensionName(
  String classSlug,
  CompilationUnitMember declaration,
) {
  final target = _classTargetSource(declaration).trimLeft();
  final privateTarget = target.startsWith('_');
  return '${privateTarget ? '_' : ''}${classSlug}AstPart';
}

String _extensionHeader(
  String source,
  CompilationUnitMember declaration,
  String extensionName,
) {
  switch (declaration) {
    case ClassDeclaration item:
      final typeParameters = item.namePart.typeParameters;
      final declarationTypeParameters =
          typeParameters == null ? '' : typeParameters.toSource();
      final target = _classTargetSource(declaration);
      return 'extension $extensionName$declarationTypeParameters on $target {';
    case ExtensionDeclaration item:
      final typeParameters = item.typeParameters;
      final declarationTypeParameters =
          typeParameters == null ? '' : typeParameters.toSource();
      final target = _classTargetSource(declaration);
      return 'extension $extensionName$declarationTypeParameters on $target {';
    default:
      throw StateError('Unsupported class-like declaration.');
  }
}

String _withPartOf(File generatedFile, File libraryFile, String body) {
  return '$_marker\npart of \'${_partOfUri(generatedFile, libraryFile)}\';\n\n$body\n';
}

class _Range {
  const _Range(this.start, this.end);

  final int start;
  final int end;
}

class _GeneratedFile {
  const _GeneratedFile({required this.file, required this.source});

  final File file;
  final String source;
}

class _Fragment {
  const _Fragment({required this.category, required this.source});

  final String category;
  final String source;
}

class _TargetPlan {
  _TargetPlan({
    required this.sourceFile,
    required this.libraryFile,
    required this.originalSource,
    required this.updatedSource,
    required this.generated,
    required this.movedSnippets,
  });

  final File sourceFile;
  final File libraryFile;
  final String originalSource;
  final String updatedSource;
  final List<_GeneratedFile> generated;
  final List<String> movedSnippets;
}

class _CollectionSplitPlan {
  const _CollectionSplitPlan({
    required this.edit,
    required this.generated,
    required this.movedSnippets,
  });

  final _Edit edit;
  final List<_GeneratedFile> generated;
  final List<String> movedSnippets;
}

class _MethodExtractionPlan {
  const _MethodExtractionPlan({
    required this.edit,
    required this.source,
  });

  final _Edit edit;
  final String source;
}

String _declarationSlug(CompilationUnitMember declaration) {
  return _safeIdentifier(
    switch (declaration) {
      ClassDeclaration item => item.namePart.typeName.lexeme,
      ExtensionDeclaration item => item.name?.lexeme ?? 'extension',
      _ => 'extension',
    },
  );
}

class _SplitPlan {
  _SplitPlan({
    required this.root,
    required this.targets,
    required this.libraryUpdates,
    required this.minimumLines,
    required this.maximumPartLines,
    required this.skipped,
  });

  final Directory root;
  final List<_TargetPlan> targets;
  final Map<File, String> libraryUpdates;
  final int minimumLines;
  final int maximumPartLines;
  final List<String> skipped;

  static _SplitPlan build(
    Directory root, {
    required int minimumLines,
    required int maximumPartLines,
    required bool includeTests,
    required bool resplit,
    required bool generatedOnly,
    required String splitSuffix,
    String? scope,
  }) {
    if (maximumPartLines < 80) {
      throw ArgumentError.value(
        maximumPartLines,
        '--max-part-lines',
        'must leave room for a generated part header',
      );
    }
    final dirty = _dirtyPaths(root);
    final searchRoots = <Directory>[Directory('${root.path}/lib')];
    if (includeTests) searchRoots.add(Directory('${root.path}/test'));
    final files = <File>[];
    for (final searchRoot in searchRoots) {
      if (!searchRoot.existsSync()) continue;
      files.addAll(
        searchRoot
            .listSync(recursive: true, followLinks: false)
            .whereType<File>()
            .where((file) => file.path.endsWith('.dart')),
      );
    }
    files.sort((a, b) => a.path.compareTo(b.path));

    final targets = <_TargetPlan>[];
    final skipped = <String>[];
    for (final file in files) {
      final relativePath = _relativeToRoot(root, file);
      if (scope != null &&
          !(relativePath == scope || relativePath.startsWith('$scope/'))) {
        continue;
      }
      final source = file.readAsStringSync();
      final isGenerated = source.contains(_marker);
      if (generatedOnly != isGenerated) continue;
      if (_lineCount(source) <= minimumLines) continue;
      if (isGenerated && !generatedOnly) continue;
      if (dirty.contains(relativePath)) {
        skipped.add('$relativePath (dirty checkout)');
        continue;
      }
      final parsed = parseString(
        content: source,
        path: file.path,
        throwIfDiagnostics: false,
      );
      if (parsed.errors.isNotEmpty) {
        skipped.add('$relativePath (parse diagnostics)');
        continue;
      }
      final partOf =
          parsed.unit.directives.whereType<PartOfDirective>().singleOrNull;
      final libraryFile = partOf == null
          ? _canonicalFile(file.path)
          : _canonicalFile(
              file.parent.path +
                  '/' +
                  _normalPath(partOf.uri?.stringValue ?? ''),
            );
      if (!libraryFile.existsSync()) {
        skipped.add('$relativePath (missing parent library)');
        continue;
      }
      if (!resplit && _libraryHasGeneratedParts(libraryFile)) {
        skipped.add('$relativePath (library already split)');
        continue;
      }
      final libraryRelative = _relativeToRoot(root, libraryFile);
      if (dirty.contains(libraryRelative) && libraryFile.path != file.path) {
        skipped.add('$relativePath (dirty parent library)');
        continue;
      }
      final target = _buildTarget(
        root: root,
        sourceFile: file,
        libraryFile: libraryFile,
        source: source,
        unit: parsed.unit,
        maximumPartLines: maximumPartLines,
        resplit: resplit,
        splitSuffix: splitSuffix,
      );
      if (target == null) {
        skipped.add('$relativePath (no verified AST boundary)');
      } else {
        targets.add(target);
      }
    }

    final groupedTargets = <String, List<_TargetPlan>>{};
    for (final target in targets) {
      groupedTargets
          .putIfAbsent(_canonicalPath(target.libraryFile.path), () => [])
          .add(target);
    }
    final libraryUpdates = <File, String>{};
    for (final entry in groupedTargets.entries) {
      final libraryFile = entry.value.first.libraryFile;
      final source = entry.value.firstWhere(
        (target) => target.sourceFile.path == libraryFile.path,
        orElse: () => _TargetPlan(
          sourceFile: libraryFile,
          libraryFile: libraryFile,
          originalSource: libraryFile.readAsStringSync(),
          updatedSource: libraryFile.readAsStringSync(),
          generated: const [],
          movedSnippets: const [],
        ),
      );
      var updated = source.updatedSource;
      final parsed = parseString(
        content: updated,
        path: libraryFile.path,
        throwIfDiagnostics: false,
      );
      if (parsed.errors.isNotEmpty) {
        throw StateError(
          'The parent library ${libraryFile.path} became unparsable before '
          'part insertion: ${parsed.errors.join('\n')}',
        );
      }
      final generatedFiles = <File>[];
      for (final target in entry.value) {
        generatedFiles.addAll(target.generated.map((item) => item.file));
      }
      final existingUris = parsed.unit.directives
          .whereType<PartDirective>()
          .map((directive) => directive.uri.stringValue)
          .whereType<String>()
          .toSet();
      final newUris = generatedFiles
          .map((file) => _partUri(libraryFile, file))
          .where((uri) => !existingUris.contains(uri))
          .toList();
      if (newUris.isNotEmpty) {
        final refreshed = parseString(
          content: updated,
          path: libraryFile.path,
          throwIfDiagnostics: false,
        ).unit;
        final parts = refreshed.directives.whereType<PartDirective>().toList();
        final insertionOffset = parts.isNotEmpty
            ? parts.last.end
            : (refreshed.declarations.isNotEmpty
                ? refreshed.declarations.first.offset
                : updated.length);
        final directives = newUris.map((uri) => "part '$uri';").join('\n');
        updated = updated.replaceRange(
          insertionOffset,
          insertionOffset,
          '\n$directives\n',
        );
      }
      if (updated != libraryFile.readAsStringSync()) {
        libraryUpdates[libraryFile] = updated;
      }
    }

    return _SplitPlan(
      root: root,
      targets: targets,
      libraryUpdates: libraryUpdates,
      minimumLines: minimumLines,
      maximumPartLines: maximumPartLines,
      skipped: skipped,
    );
  }
}

bool _libraryHasGeneratedParts(File libraryFile) {
  final parsed = parseString(
    content: libraryFile.readAsStringSync(),
    path: libraryFile.path,
    throwIfDiagnostics: false,
  );
  if (parsed.errors.isNotEmpty) return false;
  for (final directive in parsed.unit.directives.whereType<PartDirective>()) {
    final uri = directive.uri.stringValue;
    if (uri == null) continue;
    final part =
        _canonicalFile(libraryFile.parent.path + '/' + _normalPath(uri));
    if (part.existsSync() && part.readAsStringSync().contains(_marker)) {
      return true;
    }
  }
  return false;
}

_CollectionSplitPlan? _buildCollectionSplit({
  required String source,
  required VariableDeclaration variable,
  required bool isConst,
  required bool isFinal,
  required File sourceFile,
  required File libraryFile,
  required String namePrefix,
  required String variableName,
  required int maximumPartLines,
  required String splitSuffix,
}) {
  final initializer = variable.initializer;
  final isList = initializer is ListLiteral;
  final isSetOrMap = initializer is SetOrMapLiteral;
  if (!isList && !isSetOrMap) return null;
  if (!isConst && !isFinal) return null;

  final elements = <AstNode>[
    if (initializer is ListLiteral) ...initializer.elements,
    if (initializer is SetOrMapLiteral) ...initializer.elements,
  ];
  if (elements.length < 2 || initializer == null) return null;
  final initializerLines = _lineCount(
    source.substring(initializer.offset, initializer.end),
  );
  if (initializerLines <= maximumPartLines) return null;

  final chunkLimit =
      maximumPartLines > 100 ? maximumPartLines - 6 : maximumPartLines;
  final chunks = <List<String>>[];
  var current = <String>[];
  var currentLines = 0;
  for (final element in elements) {
    var elementSource = source.substring(element.offset, element.end).trim();
    if (elementSource.endsWith(',')) {
      elementSource = elementSource.substring(0, elementSource.length - 1);
    }
    final elementLines = _lineCount(elementSource) + 1;
    if (current.isNotEmpty && currentLines + elementLines > chunkLimit) {
      chunks.add(current);
      current = <String>[];
      currentLines = 0;
    }
    current.add(elementSource);
    currentLines += elementLines;
  }
  if (current.isNotEmpty) chunks.add(current);
  if (chunks.length < 2) return null;

  final slug = _safeIdentifier(variableName);
  final symbols = <String>[];
  final generated = <_GeneratedFile>[];
  final keyword = isConst ? 'const' : 'final';
  for (var index = 0; index < chunks.length; index++) {
    final partNumber = (index + 1).toString().padLeft(2, '0');
    final symbol = _safeIdentifier(
      '_${namePrefix}_${slug}${splitSuffix}Part$partNumber',
    );
    symbols.add(symbol);
    final file = File(
      '${sourceFile.parent.path}/${_withoutExtension(sourceFile.path)}_'
      '${slug}${splitSuffix}_collection_$partNumber.dart',
    );
    final opening = isList ? '[' : '{';
    final closing = isList ? ']' : '}';
    final body = '$keyword $symbol = $opening\n'
        '${chunks[index].map((item) => '$item,').join('\n')}\n$closing;';
    generated.add(
      _GeneratedFile(
        file: file,
        source: _withPartOf(file, libraryFile, body),
      ),
    );
  }

  final spread = symbols.map((symbol) => '...$symbol').join(', ');
  final replacement = isList ? '[$spread]' : '{$spread}';
  return _CollectionSplitPlan(
    edit: _Edit(initializer.offset, initializer.end, replacement),
    generated: generated,
    movedSnippets: generated.map((item) => item.source).toList(),
  );
}

_CollectionSplitPlan? _buildStaticFieldHoist({
  required String source,
  required VariableDeclaration variable,
  required bool isConst,
  required File sourceFile,
  required File libraryFile,
  required String classSlug,
  required String splitSuffix,
  required Set<String> staticNames,
}) {
  final initializer = variable.initializer;
  if (!isConst || initializer == null) return null;
  final initializerSource =
      source.substring(initializer.offset, initializer.end).trim();
  final otherStaticNames = staticNames.difference({variable.name.lexeme});
  for (final name in otherStaticNames) {
    if (RegExp('\\b${RegExp.escape(name)}\\b')
        .hasMatch(initializerSource)) {
      return null;
    }
  }

  final symbol = _safeIdentifier(
    '_${_withoutExtension(sourceFile.path)}_${classSlug}_'
    '${variable.name.lexeme}${splitSuffix}Value',
  );
  final file = File(
    '${sourceFile.parent.path}/${_withoutExtension(sourceFile.path)}_'
    '${classSlug}${splitSuffix}_static_${_safeIdentifier(variable.name.lexeme)}.dart',
  );
  final body = 'const $symbol = $initializerSource;';
  return _CollectionSplitPlan(
    edit: _Edit(initializer.offset, initializer.end, symbol),
    generated: [
      _GeneratedFile(
        file: file,
        source: _withPartOf(file, libraryFile, body),
      ),
    ],
    movedSnippets: [body],
  );
}

_MethodExtractionPlan? _buildStaticMethodExtraction({
  required String source,
  required MethodDeclaration method,
  required CompilationUnitMember declaration,
  required String classSlug,
  required String splitSuffix,
}) {
  if (method.isGetter || method.isSetter || method.isOperator) return null;
  if (method.externalKeyword != null || method.body is EmptyFunctionBody) {
    return null;
  }
  final parameters = method.parameters;
  if (parameters == null) return null;
  final arguments = _forwardingArguments(parameters);
  if (arguments == null) return null;
  final modifier = method.modifierKeyword;
  if (modifier == null) return null;
  final methodStart = method.offset;
  final helperName = _safeIdentifier(
    '_${classSlug}_${method.name.lexeme}${splitSuffix}AstPart',
  );
  var helperSource = source.substring(methodStart, method.end);
  helperSource = _applyEdits(helperSource, [
    _Edit(
      modifier.offset - methodStart,
      modifier.end - methodStart,
      '',
    ),
    _Edit(
      method.name.offset - methodStart,
      method.name.end - methodStart,
      helperName,
    ),
  ]);
  helperSource = _qualifyStaticReferences(helperSource, declaration);

  final methodPrefix =
      source.substring(methodStart, method.body.offset).trimRight();
  final typeArguments = method.typeParameters == null
      ? ''
      : '<${method.typeParameters!.typeParameters.map((item) => item.name.lexeme).join(', ')}>';
  final wrapper = '$methodPrefix => $helperName$typeArguments($arguments);';
  final replacement =
      source.substring(_annotatedStart(method), methodStart) + wrapper;
  return _MethodExtractionPlan(
    edit: _Edit(_annotatedStart(method), method.end, replacement),
    source: helperSource,
  );
}

_MethodExtractionPlan? _buildBuildMethodExtraction({
  required String source,
  required MethodDeclaration method,
  required CompilationUnitMember declaration,
  required String classSlug,
  required String splitSuffix,
}) {
  if (method.name.lexeme != 'build' ||
      method.isStatic ||
      method.isGetter ||
      method.isSetter ||
      method.isOperator ||
      method.externalKeyword != null ||
      method.body is EmptyFunctionBody ||
      RegExp(r'\bsuper\b').hasMatch(method.toSource())) {
    return null;
  }
  final parameters = method.parameters;
  if (parameters == null) return null;
  final arguments = _forwardingArguments(parameters);
  if (arguments == null) return null;
  final methodStart = method.offset;
  final helperName = _safeIdentifier(
    '_${classSlug}${splitSuffix}BuildAstPart',
  );
  var helperSource = source.substring(methodStart, method.end);
  helperSource = _applyEdits(helperSource, [
    _Edit(
      method.name.offset - methodStart,
      method.name.end - methodStart,
      helperName,
    ),
  ]);
  helperSource = _qualifyStaticReferences(helperSource, declaration);
  final methodPrefix =
      source.substring(methodStart, method.body.offset).trimRight();
  final replacement = source.substring(_annotatedStart(method), methodStart) +
      '$methodPrefix => $helperName($arguments);';
  return _MethodExtractionPlan(
    edit: _Edit(_annotatedStart(method), method.end, replacement),
    source: helperSource,
  );
}

String? _forwardingArguments(FormalParameterList parameters) {
  final arguments = <String>[];
  for (final parameter in parameters.parameters) {
    final name = parameter.name?.lexeme;
    if (name == null) return null;
    arguments.add(parameter.isNamed ? '$name: $name' : name);
  }
  return arguments.join(', ');
}

_TargetPlan? _buildTarget({
  required Directory root,
  required File sourceFile,
  required File libraryFile,
  required String source,
  required CompilationUnit unit,
  required int maximumPartLines,
  required bool resplit,
  required String splitSuffix,
}) {
  final edits = <_Edit>[];
  final generated = <_GeneratedFile>[];
  final movedSnippets = <String>[];
  final transformedDeclarations = <CompilationUnitMember>{};
  final staticMethodsByClass = <String, List<String>>{};
  var partIndex = 0;

  for (final declaration in unit.declarations) {
    if (declaration is! TopLevelVariableDeclaration ||
        declaration.variables.variables.length != 1) {
      continue;
    }
    final variables = declaration.variables;
    final variable = variables.variables.single;
    final collection = _buildCollectionSplit(
      source: source,
      variable: variable,
      isConst: variables.isConst,
      isFinal: variables.isFinal,
      sourceFile: sourceFile,
      libraryFile: libraryFile,
      namePrefix: _safeIdentifier(_withoutExtension(sourceFile.path)),
      variableName: variable.name.lexeme,
      maximumPartLines: maximumPartLines,
      splitSuffix: splitSuffix,
    );
    if (collection == null) continue;
    edits.add(collection.edit);
    generated.addAll(collection.generated);
    movedSnippets.addAll(collection.movedSnippets);
  }

  for (final declaration in unit.declarations) {
    if (declaration is! ClassDeclaration &&
        declaration is! ExtensionDeclaration) {
      continue;
    }
    final declarationLines = _lineCount(
      source.substring(declaration.offset, declaration.end),
    );
    final extensionHasAccessor = declaration is ExtensionDeclaration &&
        _classMembers(declaration)
            .whereType<MethodDeclaration>()
            .any((method) => method.isGetter || method.isSetter);
    if (declarationLines <= maximumPartLines && !extensionHasAccessor) {
      continue;
    }
    final classSlug = _declarationSlug(declaration);
    final classFieldEdits = <_Edit>[];
    final staticMethodEdits = <_Edit>[];
    for (final member in _classMembers(declaration)) {
      if (member is! FieldDeclaration || !member.isStatic) continue;
      if (member.fields.variables.length != 1) continue;
      final variables = member.fields;
      final variable = variables.variables.single;
      final collection = _buildCollectionSplit(
        source: source,
        variable: variable,
        isConst: variables.isConst,
        isFinal: variables.isFinal,
        sourceFile: sourceFile,
        libraryFile: libraryFile,
        namePrefix: _safeIdentifier(
          '${_withoutExtension(sourceFile.path)}_${_categoryFor(declaration)}',
        ),
        variableName: variable.name.lexeme,
        maximumPartLines: maximumPartLines,
        splitSuffix: splitSuffix,
      );
      if (collection == null) continue;
      classFieldEdits.add(collection.edit);
      generated.addAll(collection.generated);
      movedSnippets.addAll(collection.movedSnippets);
      if (!resplit) continue;
    }
    if (resplit) {
      final staticNames = _staticMemberNames(declaration);
      for (final member in _classMembers(declaration)) {
        if (member is! FieldDeclaration || !member.isStatic) continue;
        if (member.fields.variables.length != 1) continue;
        final variables = member.fields;
        final variable = variables.variables.single;
        final collection = _buildCollectionSplit(
          source: source,
          variable: variable,
          isConst: variables.isConst,
          isFinal: variables.isFinal,
          sourceFile: sourceFile,
          libraryFile: libraryFile,
          namePrefix: _safeIdentifier(
            '${_withoutExtension(sourceFile.path)}_${_categoryFor(declaration)}',
          ),
          variableName: variable.name.lexeme,
          maximumPartLines: maximumPartLines,
          splitSuffix: splitSuffix,
        );
        if (collection != null) continue;
        final hoist = _buildStaticFieldHoist(
          source: source,
          variable: variable,
          isConst: variables.isConst,
          sourceFile: sourceFile,
          libraryFile: libraryFile,
          classSlug: classSlug,
          splitSuffix: splitSuffix,
          staticNames: staticNames,
        );
        if (hoist == null) continue;
        classFieldEdits.add(hoist.edit);
        generated.addAll(hoist.generated);
        movedSnippets.addAll(hoist.movedSnippets);
      }
    }
    final movableMethods = _classMembers(declaration)
        .whereType<MethodDeclaration>()
        .where(
          (method) =>
              _isMovableMethod(method, allowAccessors: resplit) &&
              (resplit ||
                  _lineCount(source.substring(
                          _annotatedStart(method), method.end)) <=
                      maximumPartLines),
        )
        .toList();
    final buildMethodPlan = resplit && declarationLines > maximumPartLines
        ? _classMembers(declaration)
            .whereType<MethodDeclaration>()
            .map(
              (method) => _buildBuildMethodExtraction(
                source: source,
                method: method,
                declaration: declaration,
                classSlug: classSlug,
                splitSuffix: splitSuffix,
              ),
            )
            .whereType<_MethodExtractionPlan>()
            .firstOrNull
        : null;
    if (resplit && declarationLines > maximumPartLines) {
      for (final method
          in _classMembers(declaration).whereType<MethodDeclaration>()) {
        if (!method.isStatic) continue;
        final extraction = _buildStaticMethodExtraction(
          source: source,
          method: method,
          declaration: declaration,
          classSlug: classSlug,
          splitSuffix: splitSuffix,
        );
        if (extraction == null) continue;
        staticMethodEdits.add(extraction.edit);
        staticMethodsByClass
            .putIfAbsent(classSlug, () => <String>[])
            .add(extraction.source);
        movedSnippets.add(extraction.source);
      }
    }
    if (movableMethods.isEmpty &&
        classFieldEdits.isEmpty &&
        staticMethodEdits.isEmpty &&
        buildMethodPlan == null) {
      if (declarationLines <= maximumPartLines) continue;
      final declarationStart = _annotatedStart(declaration);
      final classSource = source.substring(declarationStart, declaration.end);
      transformedDeclarations.add(declaration);
      final classFile = File(
        '${sourceFile.parent.path}/${_withoutExtension(sourceFile.path)}_'
        '$classSlug${splitSuffix}_class.dart',
      );
      generated.add(
        _GeneratedFile(
          file: classFile,
          source: _withPartOf(classFile, libraryFile, classSource),
        ),
      );
      edits.add(_Edit(declarationStart, declaration.end, ''));
      movedSnippets.add(classSource);
      continue;
    }

    final ranges = <_Range>[];
    final methods = <String>[];
    for (final method in movableMethods) {
      final start = _annotatedStart(method);
      final methodSource = source.substring(start, method.end);
      final generatedMethodSource = _qualifyStaticReferences(
        methodSource,
        declaration,
      );
      ranges.add(_Range(start, method.end));
      methods.add(generatedMethodSource);
      movedSnippets.add(generatedMethodSource);
    }
    if (buildMethodPlan != null) {
      methods.add(buildMethodPlan.source);
      movedSnippets.add(buildMethodPlan.source);
    }
    final declarationBody = source.substring(
      declaration.offset,
      declaration.end,
    );
    final localEdits = <_Edit>[
      ...classFieldEdits.map(
        (edit) => _Edit(
          edit.start - declaration.offset,
          edit.end - declaration.offset,
          edit.replacement,
        ),
      ),
      ...ranges.map(
        (range) => _Edit(
          range.start - declaration.offset,
          range.end - declaration.offset,
          '',
        ),
      ),
      ...staticMethodEdits.map(
        (edit) => _Edit(
          edit.start - declaration.offset,
          edit.end - declaration.offset,
          edit.replacement,
        ),
      ),
      if (buildMethodPlan != null)
        _Edit(
          buildMethodPlan.edit.start - declaration.offset,
          buildMethodPlan.edit.end - declaration.offset,
          buildMethodPlan.edit.replacement,
        ),
    ];
    final updatedBody = _applyEdits(declarationBody, localEdits);
    final annotationPrefix = source.substring(
      _annotatedStart(declaration),
      declaration.offset,
    );
    final updatedDeclaration = '$annotationPrefix$updatedBody';
    final declarationStart = _annotatedStart(declaration);
    final shouldMoveWholeDeclaration =
        _lineCount(updatedDeclaration) > maximumPartLines;
    if (shouldMoveWholeDeclaration) {
      final classFile = File(
        '${sourceFile.parent.path}/${_withoutExtension(sourceFile.path)}_'
        '$classSlug${splitSuffix}_class.dart',
      );
      generated.add(
        _GeneratedFile(
          file: classFile,
          source: _withPartOf(classFile, libraryFile, updatedDeclaration),
        ),
      );
      edits.add(_Edit(declarationStart, declaration.end, ''));
      movedSnippets.add(updatedDeclaration);
    } else {
      edits.add(_Edit(declarationStart, declaration.end, updatedDeclaration));
    }
    transformedDeclarations.add(declaration);

    for (var offset = 0; offset < methods.length;) {
      final chunk = <String>[];
      var chunkLines = 0;
      while (offset < methods.length) {
        final methodLines = _lineCount(methods[offset]);
        if (chunk.isNotEmpty && chunkLines + methodLines > maximumPartLines) {
          break;
        }
        chunk.add(methods[offset]);
        chunkLines += methodLines;
        offset++;
      }
      partIndex++;
      final file = File(
        '${sourceFile.parent.path}/${_withoutExtension(sourceFile.path)}_'
        '$classSlug${splitSuffix}_methods_'
        '${partIndex.toString().padLeft(2, '0')}.dart',
      );
      final extensionName = '${_extensionName(classSlug, declaration)}'
          '${partIndex.toString().padLeft(2, '0')}';
      final body = '${_extensionHeader(source, declaration, extensionName)}\n'
          '${chunk.join('\n\n')}\n}';
      generated.add(
        _GeneratedFile(
          file: file,
          source: _withPartOf(file, libraryFile, body),
        ),
      );
    }
  }

  var staticPartIndex = 0;
  for (final entry in staticMethodsByClass.entries) {
    for (var offset = 0; offset < entry.value.length;) {
      final chunk = <String>[];
      var chunkLines = 0;
      while (offset < entry.value.length) {
        final methodLines = _lineCount(entry.value[offset]);
        if (chunk.isNotEmpty && chunkLines + methodLines > maximumPartLines) {
          break;
        }
        chunk.add(entry.value[offset]);
        chunkLines += methodLines;
        offset++;
      }
      staticPartIndex++;
      final file = File(
        '${sourceFile.parent.path}/${_withoutExtension(sourceFile.path)}_'
        '${entry.key}${splitSuffix}_static_methods_'
        '${staticPartIndex.toString().padLeft(2, '0')}.dart',
      );
      generated.add(
        _GeneratedFile(
          file: file,
          source: _withPartOf(file, libraryFile, chunk.join('\n\n')),
        ),
      );
    }
  }

  final topLevelFragments = <_Fragment>[];
  for (final declaration in unit.declarations) {
    if (!_isMovableTopLevel(declaration) ||
        transformedDeclarations.contains(declaration)) {
      continue;
    }
    final declarationLines = _lineCount(
      source.substring(declaration.offset, declaration.end),
    );
    if (declarationLines > maximumPartLines) continue;
    final start = _annotatedStart(declaration);
    final declarationSource = source.substring(start, declaration.end);
    topLevelFragments.add(
      _Fragment(
        category: _categoryFor(declaration),
        source: declarationSource,
      ),
    );
    edits.add(_Edit(start, declaration.end, ''));
    movedSnippets.add(declarationSource);
  }

  var fragmentIndex = 0;
  for (var offset = 0; offset < topLevelFragments.length;) {
    final first = topLevelFragments[offset];
    final chunk = <_Fragment>[];
    var chunkLines = 0;
    while (offset < topLevelFragments.length) {
      final fragment = topLevelFragments[offset];
      final fragmentLines = _lineCount(fragment.source);
      if (chunk.isNotEmpty && chunkLines + fragmentLines > maximumPartLines) {
        break;
      }
      chunk.add(fragment);
      chunkLines += fragmentLines;
      offset++;
    }
    fragmentIndex++;
    final file = File(
      '${sourceFile.parent.path}/${_withoutExtension(sourceFile.path)}_'
      '${first.category}${splitSuffix}_part_'
      '${fragmentIndex.toString().padLeft(2, '0')}.dart',
    );
    final body = chunk.map((fragment) => fragment.source).join('\n\n');
    generated.add(
      _GeneratedFile(
        file: file,
        source: _withPartOf(file, libraryFile, body),
      ),
    );
  }

  if (generated.isEmpty) return null;
  final updatedSource = _applyEdits(source, edits);
  final generatedPaths = <String>{};
  for (final output in generated) {
    final relative = _relativeToRoot(root, output.file);
    if (!generatedPaths.add(relative)) {
      throw StateError('Duplicate generated path: $relative');
    }
    if (output.file.existsSync()) {
      final existing = output.file.readAsStringSync();
      if (existing != output.source && !existing.contains(_marker)) {
        throw StateError(
          'Refusing to overwrite an existing non-matching generated file: '
          '${output.file.path}',
        );
      }
    }
    final parsed = parseString(
      content: output.source,
      path: output.file.path,
      throwIfDiagnostics: false,
    );
    if (parsed.errors.isNotEmpty) {
      throw StateError(
        'Generated file ${output.file.path} has syntax diagnostics: '
        '${parsed.errors.join('\n')}',
      );
    }
  }
  final updatedParsed = parseString(
    content: updatedSource,
    path: sourceFile.path,
    throwIfDiagnostics: false,
  );
  if (updatedParsed.errors.isNotEmpty) {
    throw StateError(
      'Updated source ${sourceFile.path} has syntax diagnostics: '
      '${updatedParsed.errors.join('\n')}',
    );
  }
  return _TargetPlan(
    sourceFile: sourceFile,
    libraryFile: libraryFile,
    originalSource: source,
    updatedSource: updatedSource,
    generated: generated,
    movedSnippets: movedSnippets,
  );
}

class _Edit {
  const _Edit(this.start, this.end, this.replacement);

  final int start;
  final int end;
  final String replacement;
}

String _applyEdits(String source, List<_Edit> edits) {
  var output = source;
  final sorted = edits.toList()..sort((a, b) => b.start.compareTo(a.start));
  var previousStart = source.length + 1;
  for (final edit in sorted) {
    if (edit.end > previousStart) {
      throw StateError('Overlapping AST edits detected.');
    }
    output = output.replaceRange(edit.start, edit.end, edit.replacement);
    previousStart = edit.start;
  }
  return output;
}

void _verifyPlan(_SplitPlan plan) {
  final knownFiles = <String>{};
  for (final target in plan.targets) {
    if (target.originalSource == target.updatedSource &&
        target.generated.isEmpty) {
      throw StateError('Empty transform plan for ${target.sourceFile.path}.');
    }
    for (final output in target.generated) {
      final relative = _relativeToRoot(plan.root, output.file);
      if (!knownFiles.add(relative)) {
        throw StateError('Generated path appears more than once: $relative');
      }
    }
    for (final snippet in target.movedSnippets) {
      if (!target.generated.any((output) => output.source.contains(snippet))) {
        throw StateError(
          'An AST-extracted source fragment was lost from '
          '${target.sourceFile.path}.',
        );
      }
    }
  }
}

void _printPlan(_SplitPlan plan) {
  stdout.writeln(
    'Autonomous AST large-library split plan: '
    '${plan.targets.length} source files, ${plan.libraryUpdates.length} libraries',
  );
  for (final target in plan.targets) {
    final before = _lineCount(target.originalSource);
    final after = _lineCount(target.updatedSource);
    stdout.writeln(
      '  ${_relativeToRoot(plan.root, target.sourceFile)}: '
      '$before -> $after lines, ${target.generated.length} generated parts',
    );
    for (final output in target.generated) {
      stdout.writeln(
        '    ${_relativeToRoot(plan.root, output.file)}: '
        '${_lineCount(output.source)} lines',
      );
    }
  }
  if (plan.skipped.isNotEmpty) {
    stdout.writeln('Skipped safely: ${plan.skipped.length} files');
    for (final item in plan.skipped.take(80)) {
      stdout.writeln('  $item');
    }
    if (plan.skipped.length > 80) {
      stdout.writeln('  ...');
    }
  }
}

void _auditGeneratedCheckout(
  Directory root, {
  required bool includeTests,
}) {
  final searchRoots = <Directory>[Directory('${root.path}/lib')];
  if (includeTests) searchRoots.add(Directory('${root.path}/test'));
  var generatedCount = 0;
  for (final searchRoot in searchRoots) {
    if (!searchRoot.existsSync()) continue;
    final files = searchRoot
        .listSync(recursive: true, followLinks: false)
        .whereType<File>()
        .where((file) => file.path.endsWith('.dart'));
    for (final file in files) {
      final source = file.readAsStringSync();
      if (!source.contains(_marker)) continue;
      generatedCount++;
      final parsed = parseString(
        content: source,
        path: file.path,
        throwIfDiagnostics: false,
      );
      if (parsed.errors.isNotEmpty) {
        throw StateError(
          'Generated file ${file.path} has syntax diagnostics: '
          '${parsed.errors.join('\n')}',
        );
      }
      final partOf =
          parsed.unit.directives.whereType<PartOfDirective>().singleOrNull;
      final partOfUri = partOf?.uri?.stringValue;
      if (partOfUri == null) {
        throw StateError('Generated file has no part-of URI: ${file.path}');
      }
      final parent = _canonicalFile(
        file.parent.path + '/' + _normalPath(partOfUri),
      );
      if (!parent.existsSync()) {
        throw StateError('Generated file parent is missing: ${file.path}');
      }
      final parentParsed = parseString(
        content: parent.readAsStringSync(),
        path: parent.path,
        throwIfDiagnostics: false,
      );
      if (parentParsed.errors.isNotEmpty) {
        throw StateError(
          'Generated file parent has syntax diagnostics: ${parent.path}',
        );
      }
      final expectedUri = _partUri(parent, file);
      final declared = parentParsed.unit.directives
          .whereType<PartDirective>()
          .map((directive) => directive.uri.stringValue)
          .whereType<String>();
      if (!declared.contains(expectedUri)) {
        throw StateError(
          'Generated file is not declared by its parent: ${file.path}',
        );
      }
    }
  }
  if (generatedCount == 0) {
    throw StateError('No generated large-library parts were found.');
  }
}

void _repairGeneratedDirectives(
  Directory root, {
  required bool includeTests,
}) {
  final searchRoots = <Directory>[Directory('${root.path}/lib')];
  if (includeTests) searchRoots.add(Directory('${root.path}/test'));
  final additions = <String, Set<String>>{};
  for (final searchRoot in searchRoots) {
    if (!searchRoot.existsSync()) continue;
    final files = searchRoot
        .listSync(recursive: true, followLinks: false)
        .whereType<File>()
        .where((file) => file.path.endsWith('.dart'));
    for (final file in files) {
      final source = file.readAsStringSync();
      if (!source.contains(_marker)) continue;
      final parsed = parseString(
        content: source,
        path: file.path,
        throwIfDiagnostics: false,
      );
      if (parsed.errors.isNotEmpty) {
        throw StateError(
          'Generated file ${file.path} has syntax diagnostics: '
          '${parsed.errors.join('\n')}',
        );
      }
      final partOf =
          parsed.unit.directives.whereType<PartOfDirective>().singleOrNull;
      final partOfUri = partOf?.uri?.stringValue;
      if (partOfUri == null) {
        throw StateError('Generated file has no part-of URI: ${file.path}');
      }
      final parent = _canonicalFile(file.parent.path + '/' + partOfUri);
      if (!parent.existsSync()) {
        throw StateError('Generated file parent is missing: ${file.path}');
      }
      final parentPath = _canonicalPath(parent.path);
      additions
          .putIfAbsent(parentPath, () => <String>{})
          .add(_partUri(parent, file));
    }
  }

  var changedLibraries = 0;
  for (final entry in additions.entries) {
    final libraryFile = _canonicalFile(entry.key);
    var source = libraryFile.readAsStringSync();
    final parsed = parseString(
      content: source,
      path: libraryFile.path,
      throwIfDiagnostics: false,
    );
    if (parsed.errors.isNotEmpty) {
      throw StateError(
          'Parent library has syntax diagnostics: ${libraryFile.path}');
    }
    final existing = parsed.unit.directives
        .whereType<PartDirective>()
        .map((directive) => directive.uri.stringValue)
        .toSet();
    final missing =
        entry.value.where((uri) => !existing.contains(uri)).toList();
    if (missing.isEmpty) continue;
    final refreshed = parseString(
      content: source,
      path: libraryFile.path,
      throwIfDiagnostics: false,
    ).unit;
    final parts = refreshed.directives.whereType<PartDirective>().toList();
    final insertionOffset = parts.isNotEmpty
        ? parts.last.end
        : (refreshed.declarations.isNotEmpty
            ? refreshed.declarations.first.offset
            : source.length);
    source = source.replaceRange(
      insertionOffset,
      insertionOffset,
      '\n${missing.map((uri) => "part '$uri';").join('\n')}\n',
    );
    libraryFile.writeAsStringSync(source);
    changedLibraries++;
  }
  stdout.writeln(
      'Repaired generated part directives in $changedLibraries libraries.');
}

void _repairGeneratedVisibility(
  Directory root, {
  required bool includeTests,
}) {
  final searchRoots = <Directory>[Directory('${root.path}/lib')];
  if (includeTests) searchRoots.add(Directory('${root.path}/test'));
  var changedFiles = 0;
  for (final searchRoot in searchRoots) {
    if (!searchRoot.existsSync()) continue;
    final files = searchRoot
        .listSync(recursive: true, followLinks: false)
        .whereType<File>()
        .where((file) => file.path.endsWith('.dart'));
    for (final file in files) {
      var source = file.readAsStringSync();
      if (!source.contains(_marker)) continue;
      final parsed = parseString(
        content: source,
        path: file.path,
        throwIfDiagnostics: false,
      );
      if (parsed.errors.isNotEmpty) {
        throw StateError(
          'Generated file ${file.path} has syntax diagnostics: '
          '${parsed.errors.join('\n')}',
        );
      }
      final edits = <_Edit>[];
      for (final extension
          in parsed.unit.declarations.whereType<ExtensionDeclaration>()) {
        final name = extension.name;
        final target = extension.onClause?.extendedType.toSource().trimLeft();
        if (name == null || !name.lexeme.startsWith('_') || target == null) {
          continue;
        }
        if (target.startsWith('_')) continue;
        edits.add(
          _Edit(
            name.offset,
            name.end,
            name.lexeme.substring(1),
          ),
        );
      }
      if (edits.isEmpty) continue;
      source = _applyEdits(source, edits);
      file.writeAsStringSync(source);
      changedFiles++;
    }
  }
  stdout.writeln(
      'Repaired generated extension visibility in $changedFiles files.');
}

void _applyPlan(_SplitPlan plan) {
  final existingBackups = <File, String>{};
  final newFiles = <File>[];
  for (final target in plan.targets) {
    if (!existingBackups.containsKey(target.sourceFile)) {
      existingBackups[target.sourceFile] = target.sourceFile.readAsStringSync();
    }
    for (final output in target.generated) {
      if (output.file.existsSync()) {
        existingBackups[output.file] = output.file.readAsStringSync();
      } else {
        newFiles.add(output.file);
      }
    }
  }
  for (final file in plan.libraryUpdates.keys) {
    if (!existingBackups.containsKey(file)) {
      existingBackups[file] = file.readAsStringSync();
    }
  }
  try {
    for (final target in plan.targets) {
      target.sourceFile.writeAsStringSync(target.updatedSource);
      for (final output in target.generated) {
        output.file.parent.createSync(recursive: true);
        output.file.writeAsStringSync(output.source);
      }
    }
    for (final entry in plan.libraryUpdates.entries) {
      entry.key.writeAsStringSync(entry.value);
    }
  } catch (_) {
    for (final entry in existingBackups.entries) {
      entry.key.parent.createSync(recursive: true);
      entry.key.writeAsStringSync(entry.value);
    }
    for (final file in newFiles) {
      if (file.existsSync()) file.deleteSync();
    }
    rethrow;
  }
}
